28	OvercommitResult OvercommitTracker::needToStopQuery(MemoryTracker * tracker, Int64 amount)
29	{
30	    DENY_ALLOCATIONS_IN_SCOPE;
31	
32	    if (OvercommitTrackerBlockerInThread::isBlocked())
33	        return OvercommitResult::NONE;
34	    // NOTE: Do not change the order of locks
35	    //
36	    // global_mutex must be acquired before overcommit_m, because
37	    // method OvercommitTracker::onQueryStop(MemoryTracker *) is
38	    // always called with already acquired global_mutex in
39	    // ProcessListEntry::~ProcessListEntry().
40	    std::unique_lock<std::mutex> global_lock(global_mutex);
41	    std::unique_lock<std::mutex> lk(overcommit_m);
42	
43	    size_t id = next_id++;
44	
45	    auto max_wait_time = tracker->getOvercommitWaitingTime();
46	
47	    if (max_wait_time == ZERO_MICROSEC)
48	        return OvercommitResult::DISABLED;
49	
50	    pickQueryToExclude();
51	    assert(cancellation_state != QueryCancellationState::NONE);
52	    global_lock.unlock();
53	
54	    // If no query was chosen we need to stop current query.
55	    // This may happen if no soft limit is set.
56	    if (picked_tracker == nullptr)
57	    {
58	        // Here state can not be RUNNING, because it requires
59	        // picked_tracker to be not null pointer.
60	        assert(cancellation_state == QueryCancellationState::SELECTED);
61	        cancellation_state = QueryCancellationState::NONE;
62	        return OvercommitResult::DISABLED;
63	    }
64	    if (picked_tracker == tracker)
65	    {
66	        // Query of the provided as an argument memory tracker was chosen.
67	        // It may happen even when current state is RUNNING, because
68	        // ThreadStatus::~ThreadStatus may call MemoryTracker::alloc.
69	        cancellation_state = QueryCancellationState::RUNNING;
70	        return OvercommitResult::SELECTED;
71	    }
72	
73	    allow_release = true;
74	
75	    required_memory += amount;
76	    auto wait_start_time = std::chrono::system_clock::now();
77	    bool timeout = !cv.wait_for(lk, max_wait_time, [this, id]()
78	    {
79	        return id < id_to_release || cancellation_state == QueryCancellationState::NONE;
80	    });
81	    auto wait_end_time = std::chrono::system_clock::now();
82	    ProfileEvents::increment(ProfileEvents::MemoryOvercommitWaitTimeMicroseconds, (wait_end_time - wait_start_time) / 1us);
83	
84	    required_memory -= amount;
85	    bool still_need = !(id < id_to_release); // True if thread wasn't released
86	
87	    // If threads where not released since last call of this method,
88	    // we can release them now.
89	    if (allow_release && required_memory <= freed_memory && still_need)
90	        releaseThreads();
91	
92	    // All required amount of memory is free now and selected query to stop doesn't know about it.
93	    // As we don't need to free memory, we can continue execution of the selected query.
94	    if (required_memory == 0 && cancellation_state == QueryCancellationState::SELECTED)
95	        reset();
96	    if (timeout)
97	        return OvercommitResult::TIMEOUTED;
98	    if (still_need)
99	        return OvercommitResult::NOT_ENOUGH_FREED;
100	    else
101	        return OvercommitResult::MEMORY_FREED;
102	}
