104	void OvercommitTracker::tryContinueQueryExecutionAfterFree(Int64 amount)
105	{
106	    DENY_ALLOCATIONS_IN_SCOPE;
107	
108	    if (OvercommitTrackerBlockerInThread::isBlocked())
109	        return;
110	
111	    std::lock_guard guard(overcommit_m);
